const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries
  const antakya = ee.Geometry.Point([36.1497, 36.2066]).buffer(2000); // Central Antakya
  const hatayAirport = ee.Geometry.Point([36.2822, 36.3711]).buffer(2000); // Hatay Airport area

  // Get VIIRS nighttime lights for Feb 14, 2023
  const date = '2023-02-14';
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate(date, '2023-02-15');

  // Check if collection is empty
  const count = viirs.size().getInfo();
  if (count === 0) {
    print("No VIIRS data found for Feb 14, 2023");
    print("<answer>C1</answer>");
    return;
  }

  // Get the image and select avg_rad band
  const image = viirs.first();

  // Calculate mean radiance for both regions
  const antakyaStats = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: antakya,
    scale: 1000,
    maxPixels: 1e9
  });

  const airportStats = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hatayAirport,
    scale: 1000,
    maxPixels: 1e9
  });

  const antakyaRad = antakyaStats.get('avg_rad').getInfo();
  const airportRad = airportStats.get('avg_rad').getInfo();

  // Check for valid results
  if (antakyaRad === null || airportRad === null || 
      isNaN(antakyaRad) || isNaN(airportRad)) {
    print("Invalid calculation results");
    print("<answer>C3</answer>");
    return;
  }

  // Print results and determine answer
  print(`Antakya radiance: ${antakyaRad.toFixed(2)}`);
  print(`Airport radiance: ${airportRad.toFixed(2)}`);
  print(`Antakya brighter: ${antakyaRad > airportRad}`);

  if (antakyaRad > airportRad) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
